const K = parseInt(readline());
const R = readline();
const M = readline();
const diff = [...R].map((c, i) => c !== M[i] ? 1 : 0);
let cur = diff.slice(0, K).reduce((a, b) => a + b, 0);
let best = cur;
for (let i = K; i < diff.length; i++) {
    cur += diff[i] - diff[i - K];
    best = Math.max(best, cur);
}
console.log(best);
